// Author: MiYu. Native calls preserve session bindings and reject unsupported binary value categories.
#include "jass_binary_bridge.h"
#include <bit>
#include <stdexcept>

namespace war3 {
JassBinaryNativeValue invokeJass2Native(jass::Runtime& runtime,const JassBinaryProgram& program,const std::string& name,std::span<const JassBinaryNativeValue> arguments){
    auto& module=runtime.module();auto id=module.functionId(name);if(id==jass::none || !module.program().functions()[id].native)throw std::runtime_error("Unknown 2SAJ native: "+name);auto& signature=module.functions()[id];if(arguments.size()!=signature.parameters.size())throw std::runtime_error("2SAJ native argument count differs: "+name);std::vector<jass::Value> converted;converted.reserve(arguments.size());for(size_t i=0;i<arguments.size();++i){auto& arg=arguments[i];auto type=signature.parameters[i];auto category=module.type(type).category;if(arg.type==2 && !arg.bits && !arg.text && (category==jass::Category::String || category==jass::Category::Handle || category==jass::Category::Code))converted.push_back({module.typeId("<null>"),0,{}});else if(arg.type==4 && category==jass::Category::Integer)converted.push_back(runtime.integer(std::bit_cast<std::int32_t>(arg.bits)));else if(arg.type==5 && category==jass::Category::Real)converted.push_back(runtime.real(jass::Real::fromBits(arg.bits)));else if(arg.type==8 && category==jass::Category::Boolean && arg.bits<=1)converted.push_back(runtime.boolean(arg.bits!=0));else if(arg.type==7 && category==jass::Category::Handle)converted.push_back(runtime.handle(module.type(type).name,arg.bits));else if(arg.type==6 && category==jass::Category::String){if(arg.text && arg.bits)throw std::runtime_error("Ambiguous 2SAJ string");if(arg.text)converted.push_back(runtime.string(*arg.text));else if(!arg.bits)converted.push_back({type,0,{}});else{if(arg.bits>program.symbols.size())throw std::runtime_error("Invalid 2SAJ string symbol");converted.push_back(runtime.string(program.symbols[arg.bits-1]));}}else throw std::runtime_error("Unsupported 2SAJ native argument: "+name+" #"+std::to_string(i)+" type="+std::to_string(arg.type)+" expected="+module.type(type).name);}
    auto value=runtime.invoke(name,converted);switch(module.type(value.type).category){case jass::Category::Nothing:return {0,0,{}};case jass::Category::Integer:return {4,value.bits,{}};case jass::Category::Real:return {5,value.bits,{}};case jass::Category::String:return {6,0,value.text};case jass::Category::Handle:return {7,value.bits,{}};case jass::Category::Boolean:return {8,value.bits,{}};default:throw std::runtime_error("Unsupported 2SAJ native result: "+name);}
}
}
